from author_csharp_v2 import *

unit(80,
"Task نمایندهٔ پایان یک کار و Task<T> پایان همراه نتیجه است؛ task الزاماً thread نیست. async اجازهٔ await می‌دهد و به‌تنهایی کار را parallel یا روی thread تازه اجرا نمی‌کند. await تکمیل task را بدون blocking معمول همان thread انتظار می‌کشد و خطا را به مصرف‌کننده منتقل می‌کند. برای I/O از API async واقعی استفاده کن؛ Task.Run بیشتر برای انتقال کار CPU-bound به pool در context مناسب است، نه پوشاندن هر I/O. async Main نقطهٔ ورود منتظرشونده می‌دهد. async void عمدتاً برای event handler لازم است؛ مصرف‌کنندهٔ معمول باید Task بگیرد تا پایان و خطا را مشاهده کند. Result/Wait می‌تواند blocking و مشکلات context بسازد.",
'int result=await Task.FromResult(4);Console.WriteLine(result);', '4',
("وجود async روی متد چه چیزی را تضمین نمی‌کند؟", "ساخت thread تازه یا اجرای parallel", "امکان نوشتن await در بدنهٔ مجاز", "برگشت قرارداد async مانند Task", "async تبدیل کنترل جریان است؛ نوع کار و scheduler تعیین می‌کنند چه چیزی کجا اجرا شود."),
conflict("async الزاماً thread نیست", "دو ادعا دربارهٔ همان فراخوانی async بدون Task.Run هستند؛ کوچک‌ترین ناسازگاری را پیدا کن.", ["این اجرا هیچ thread تازه‌ای ایجاد نکرده است", "هر فراخوانی async حتماً یک thread تازه می‌سازد", "خروجی متد Task<int> است"], [([0,1],[0,1],"یک مورد async بدون thread تازه،ادعای همیشگی ساخت thread را نقض می‌کند.")]),
"متد async دارای Task<int> بساز و نتیجه و exception آن را با await مشاهده کن. async void به کار نبر؛ توضیح بده چرا برای I/O واقعی Task.Run لازم نیست.",
'Console.WriteLine(await CalculateAsync(false));\ntry {await CalculateAsync(true);} catch(InvalidOperationException) {Console.WriteLine("observed");}\nstatic async Task<int> CalculateAsync(bool fail)\n{\n    await Task.CompletedTask;if(fail) throw new InvalidOperationException("failure");return 7;\n}',
"7 و observed چاپ شود. خطا به task مصرف‌شده برسد و هیچ fire-and-forget بی‌مالک یا blocking انتظار وجود نداشته باشد.")

unit(81,
"ساخت یا فراخوانی task و await کردن آن دو رویداد متفاوت‌اند؛ await پشت‌سرهم روی عملیاتِ هنوز شروع‌نشده می‌تواند اجرا را ترتیبی کند. WhenAll پایان همه را انتظار می‌کشد و نتیجه‌ها را به ترتیب ورودی می‌دهد،نه ترتیب تکمیل. اگر چند task خراب شوند،task ترکیبی همهٔ خطاها را در Exception نگه می‌دارد ولی await معمولاً یک خطا را پرتاب می‌کند؛ برای گزارش کامل باید taskها یا AggregateException بررسی شوند. WhenAny task برنده را می‌دهد و خود نتیجهٔ آن هنوز نیاز به await دارد؛ taskهای بازنده هم مالک و مشاهدهٔ خطا می‌خواهند. ContinueWith و Unwrap در کد موجود را با scheduler و task تو‌در‌تو بخوان؛ await غالباً خواناتر است.",
'var results=await Task.WhenAll(Task.FromResult(2),Task.FromResult(3));\nConsole.WriteLine(string.Join(",",results));', '2,3',
("بعد از await Task.WhenAny(tasks) چه چیزی هنوز لازم است؟", "await برنده و تعیین تکلیف بقیهٔ taskها", "فرض موفق بودن برنده بدون مشاهدهٔ نتیجه", "رهاکردن همیشگی خطاهای بازنده", "WhenAny خود نتیجه یا موفقیت کار برنده را تضمین نمی‌کند؛ مالکیت همهٔ کارها باید حفظ شود."),
constraints("مشاهدهٔ همهٔ کارها", "دو task مستقل می‌توانند به هر ترتیب شروع شوند؛ پایان ترکیبی و بررسی خطا وابستگی مشخص دارند.", ["شروع A", "شروع B", "ساخت WhenAll از A و B", "await ترکیب", "بررسی خطاهای لازم و cleanup"], [[0,2],[1,2],[2,3],[3,4]]),
"دو task موفق و دو task خطادار ترکیب کن. ترتیب نتیجهٔ موفق با ورودی یکسان بماند؛ هر دو خطای ترکیب ناموفق مشاهده و شمارش شوند.",
'Console.WriteLine(string.Join(",",await Task.WhenAll(Task.FromResult(2),Task.FromResult(1))));\nTask all=Task.WhenAll(Task.FromException(new InvalidOperationException("A")),Task.FromException(new ArgumentException("B")));\ntry {await all;} catch {Console.WriteLine(all.Exception!.InnerExceptions.Count);}',
"2,1 و 2 چاپ شود. catch فقط برای مشاهدهٔ تست باشد و مسیر واقعی علت خطاها را حفظ کند؛ task رهاشده باقی نماند.")

unit(82,
"CancellationToken درخواست لغو را منتقل و CancellationTokenSource عمر و صدور آن را کنترل می‌کند. لغو تعاونی است: عملیات باید token را بررسی یا به API زیرین بدهد. CancelAfter درخواست آینده می‌دهد و linked token چند منبع لغو را ترکیب می‌کند؛ Source و registrationها مالک Dispose می‌خواهند. OperationCanceledException لغوِ قراردادشده را از خطای عادی جدا می‌کند. Task.WaitAsync می‌تواند انتظار را timeout یا لغو کند،اما لزوماً کار زیرین را متوقف نمی‌کند. بعد از timeout همچنان باید task زیرین مالک داشته باشد و خطایش مشاهده شود. لغو قبل،حین و پس از پایان باید بدون گزارش موفقیت جعلی تست شود.",
'var source=new TaskCompletionSource<int>();\ntry {await source.Task.WaitAsync(TimeSpan.Zero);} catch(TimeoutException) {Console.WriteLine("timeout");}\nConsole.WriteLine(source.Task.IsCompleted);source.SetResult(1);', 'timeout\nFalse',
("timeout در task.WaitAsync چه چیزی را الزاماً متوقف نمی‌کند؟", "عملیات اصلی پشت task", "فقط انتظار همان فراخوانی", "پرتاب TimeoutException در انتظار منقضی‌شده", "timeout انتظار با ارسال و رعایت token لغو در خود عملیات متفاوت است."),
counter("انتظار تمام شد،کار نه", "ادعا: TimeoutException از WaitAsync یعنی عملیات زیرین حتماً متوقف شده است.", ["task از TCS هنوز تکمیل نشده", "عملیات token را رعایت کرده و لغو شده"], [("IsCompleted=false پس از timeout","عملیات متوقف شده",True,"فقط انتظار تمام شده و کار هنوز مالک می‌خواهد."),("عملیات واقعاً لغو شده","عملیات متوقف شده",False,"این مسیر token را جدا رعایت کرده است.")]),
"با TCS بدون sleep نشان بده timeout انتظار،task زیرین را کامل نمی‌کند. سپس کار را تعیین تکلیف کن. متد tokenپذیر را برای لغو پیش از شروع و پس از پایان تست کن.",
'var pending=new TaskCompletionSource<int>(TaskCreationOptions.RunContinuationsAsynchronously);\ntry {await pending.Task.WaitAsync(TimeSpan.Zero);} catch(TimeoutException) {}\nif(pending.Task.IsCompleted) throw new Exception("underlying task");\npending.SetResult(4);Console.WriteLine(await pending.Task);\nusing var cts=new CancellationTokenSource();cts.Cancel();\ntry {cts.Token.ThrowIfCancellationRequested();} catch(OperationCanceledException) {Console.WriteLine("cancelled");}',
"4 و cancelled چاپ شود. task زیرین پس از timeout رها نشود؛ لغو با خطای عادی یا موفقیت مخلوط نشود.")

unit(83,
"IAsyncDisposable cleanup قابل انتظار را با DisposeAsync و ValueTask بیان می‌کند. await using در خروج scope،از جمله خطا یا لغو،cleanup را await می‌کند. await در catch و finally مجاز است،اما خطای cleanup ممکن است خطای قبلی را تحت تأثیر قرار دهد و سیاست مشاهدهٔ هر دو باید روشن باشد. ValueTask برای قرارداد مصرف خاص است؛ مصرف عمومی بهتر است یک بار await شود و برای نگهداری یا ترکیب در صورت نیاز به Task تبدیل گردد. Result و Wait روی کد async به blocking و deadlock یا starvation می‌انجامد. fire-and-forget بدون مالک،خطا و پایان را گم می‌کند؛ کار پس‌زمینه به میزبان و سیاست shutdown نیاز دارد.",
'await using(var resource=new Resource()) {Console.WriteLine("use");}\nclass Resource:IAsyncDisposable {public ValueTask DisposeAsync(){Console.WriteLine("async dispose");return ValueTask.CompletedTask;}}', 'use\nasync dispose',
("یک ValueTask عمومیِ ناشناخته را چطور مصرف می‌کنی؟", "یک بار await طبق قرارداد؛ برای چند مصرف در صورت نیاز AsTask", "بی‌حد دوباره await بدون بررسی قرارداد", "همیشه .Result روی thread سرویس", "برخی ValueTaskها منبع قابل استفادهٔ دوباره ندارند؛ قرارداد مصرف را با Task یکی فرض نکن."),
constraints("cleanup async", "مسیر خطا هم باید cleanup را await کند و پیش از خروج task آن را تمام کند.", ["ساخت منبع async", "استفاده", "ورود به cleanup پس از خطا", "await DisposeAsync", "پایان task مصرف‌کننده"], [[0,1],[1,2],[2,3],[3,4]]),
"منبع async fake با شمارنده بساز. مسیر موفق،exception و لغو را با await using تست کن؛ قبل از تکمیل cleanup کار را تمام‌شده اعلام نکن.",
'int disposed=0;\ntry {await using var resource=new Resource(()=>disposed++);throw new OperationCanceledException();}\ncatch(OperationCanceledException) {}\nConsole.WriteLine(disposed);\nclass Resource(Action release):IAsyncDisposable {public ValueTask DisposeAsync(){release();return ValueTask.CompletedTask;}}',
"شمارنده در مسیر لغو 1 باشد و در همهٔ مسیرها cleanup await شود. ValueTask دوباره مصرف و exception رها نشود.")

unit(84,
"IAsyncEnumerable<T> عناصر را با MoveNextAsync تدریجی می‌دهد؛ await foreach پروتکل و DisposeAsync را مدیریت می‌کند. async iterator با yield return داده را به درخواست مصرف‌کننده تولید می‌کند و همین تقاضای مرحله‌ای نوعی backpressure می‌دهد؛ پیش‌واکشی جدا می‌تواند قرارداد دیگری داشته باشد. WithCancellation token را به پیمایش می‌دهد و EnumeratorCancellation پارامتر مناسب iterator را با token مصرف‌کننده مرتبط می‌کند. لغو باید به I/O زیرین هم منتقل شود. break یا exception مصرف‌کننده باید enumerator را آزاد کند. async stream با Channel که صف و producer مستقل دارد یکی نیست و تمام APIهای LINQ معمولی مستقیم روی آن قابل استفاده نیستند.",
'await foreach(int n in Values()) Console.WriteLine(n);\nstatic async IAsyncEnumerable<int> Values(){await Task.CompletedTask;yield return 1;yield return 2;}', '1\n2',
("break در await foreach چه تعهدی برای enumerator قابل آزادسازی دارد؟", "DisposeAsync آن انتظار کشیده شود.", "همیشه producer بی‌مالک در پس‌زمینه ادامه دهد.", "همهٔ داده‌ها قبل از خروج اجباری مصرف شوند.", "پروتکل مصرف async هم cleanup در خروج زودهنگام دارد؛ producer مستقل باید قرارداد مالکیت جدا داشته باشد."),
simulation("تقاضای تدریجی", "مصرف‌کننده فقط دو صفحه می‌خواهد. هر MoveNextAsync یک صفحه می‌دهد؛ سپس break و cleanup هدف است.", ["درخواست صفحهٔ بعد", "break و DisposeAsync"], ["0 صفحه،باز","1 صفحه،باز","2 صفحه،باز","2 صفحه،بسته","0 یا 1 صفحه،بسته"], [[1,4],[2,4],[-1,3],[-1,-1],[-1,-1]], [3], limit=3),
"async iterator دو صفحه بساز که token را رعایت کند. پس از اولین صفحه break کن و cleanup را با شمارنده تست کن؛ تست لغو را بدون تأخیر تصادفی بنویس.",
'using System.Runtime.CompilerServices;\nint closed=0;\nawait foreach(int n in Values()) {Console.WriteLine(n);break;}\nConsole.WriteLine(closed);\nasync IAsyncEnumerable<int> Values([EnumeratorCancellation] CancellationToken token=default)\n{\n    try {token.ThrowIfCancellationRequested();await Task.CompletedTask;yield return 1;token.ThrowIfCancellationRequested();yield return 2;}\n    finally {closed++;}\n}',
"1 و 1 چاپ شود. token به کار زیرین منتقل و break منبع را آزاد کند؛ لغو پیش از شروع و بین صفحه‌ها تست شود.")

unit(85,
"HTTP درخواست با URI،method،header و body و پاسخ با status می‌سازد. HttpClient باید طول عمر مناسب یا IHttpClientFactory داشته باشد تا اتصال‌ها و DNS درست مدیریت شوند؛ ساخت‌ودورریختن بی‌رویه policy خوبی نیست. status ناموفق،JSON خراب و خطای transport حالت‌های متفاوت‌اند. ResponseHeadersRead و stream امکان مصرف تدریجی می‌دهند و response/body مالک Dispose می‌خواهند. timeout و token لغو باید تا خواندن body منتقل شوند. retry فقط برای عملیات و خطاهای مناسب با backoff و سقف مجاز است؛ تکرار POST غیرidempotent ممکن است اثر دوباره بسازد. TLS و DNS لایه‌های شبکه‌اند و غیرفعال‌کردن validation گواهی راه رفع خطای عمومی نیست. handler fake تست را از شبکهٔ واقعی مستقل می‌کند.",
'using System.Net;using System.Net.Http;\nusing var client=new HttpClient(new Fake());\nConsole.WriteLine(await client.GetStringAsync("https://example.test/data"));\nclass Fake:HttpMessageHandler {protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token)=>Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent("ok")});}', 'ok',
("retry خودکار روی POST برداشت پول بدون قرارداد idempotency چه خطری دارد؟", "ممکن است اثر کسب‌وکاری دوباره انجام شود.", "همیشه درخواست را سریع‌تر و ایمن‌تر می‌کند.", "TLS تمام تکرارها را حذف می‌کند.", "شبکه ممکن است پاسخ را گم کند ولی اثر انجام شده باشد؛ تکرار نیاز به قرارداد idempotency و سیاست روشن دارد."),
mission("کلاینت قابل اعتماد", "خطاهای درخواست را با نوع و قراردادشان رسیدگی کن.", [("GET پاسخ 503 موقت دارد.","retry محدود با backoff و token طبق سیاست","تکرار بی‌پایان بدون لغو"),("پاسخ 200 ولی JSON خراب است.","گزارش خطای قالب و حفظ علت","اعلام موفقیت با شیء خالی"),("درخواست POST غیرidempotent timeout شده است.","بررسی قرارداد idempotency قبل از تکرار","تکرار کور بدون شناسهٔ عملیات")]),
"کلاینت JSON با HttpMessageHandler fake بساز. 200 معتبر،status ناموفق،JSON خراب و token لغو را تست کن؛ هیچ درخواست واقعی نفرست.",
'using System.Net;using System.Net.Http;using System.Net.Http.Json;\nusing var client=new HttpClient(new Fake());\nvar item=await client.GetFromJsonAsync<Item>("https://example.test/item");\nif(item is null||item.Value!=3) throw new Exception("response");Console.WriteLine(item.Value);\nrecord Item(int Value);\nclass Fake:HttpMessageHandler\n{protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token) {token.ThrowIfCancellationRequested();return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent("""{"Value":3}""")});}}',
"3 چاپ شود و چهار مسیر مستقل با fake تست شوند. client و response مالک مشخص داشته باشند؛ retry عمومی برای همهٔ methodها اضافه نشود.")

unit(86,
"Thread جریان اجرایی سیستم و ThreadPool مجموعهٔ workerهای قابل استفادهٔ دوباره است؛ Task واحد کار یا پایان است و الزاماً نسبت یک‌به‌یک با thread ندارد. foreground thread می‌تواند فرایند را زنده نگه دارد و background thread با پایان foregroundها تضمین تکمیل ندارد. کار CPU-bound پردازنده می‌خواهد؛ I/O-bound بیشتر انتظار منبع خارجی است. blocking تعداد زیاد workerها می‌تواند starvation بسازد؛ افزایش کور تعداد thread راه‌حل معماری نیست. ThreadLocal دادهٔ وابسته به thread و ExecutionContext دادهٔ جریان منطقی را منتقل می‌کند؛ با async که thread عوض می‌شود این‌ها یک معنا ندارند. آزمون باید پایان threadها را join و خطاها را منتقل کند.",
'int result=0;var thread=new Thread(()=>result=4);thread.Start();thread.Join();\nConsole.WriteLine(result);', '4',
("برای I/O async واقعی،اشغال یک ThreadPool worker با Wait چه پیامدی می‌تواند داشته باشد؟", "blocking و در بار بالا starvation", "تضمین کاهش تعداد منابع", "تبدیل خودکار همهٔ I/O به CPU-bound", "انتظار async برای آزادگذاشتن worker است؛ blocking این مزیت را از بین می‌برد."),
groups("نوع بار", "عمل غالب هر کارت را به CPU-bound و I/O-bound تقسیم کن.", ["CPU-bound", "I/O-bound"], [["فشرده‌سازی داده در حافظه","محاسبهٔ hash یک buffer بزرگ"],["انتظار پاسخ HTTP","انتظار خواندن شبکه"]]),
"یک محاسبهٔ مستقل را روی Thread انجام و با Join پایانش را مشاهده کن. نسخهٔ Task.Run را هم تست کن؛ برای خواندن HTTP از API async مستقیم استفاده کن و دلیل تفاوت را بنویس.",
'int threaded=0;var thread=new Thread(()=>threaded=Enumerable.Range(1,4).Sum());thread.Start();thread.Join();\nint tasked=await Task.Run(()=>Enumerable.Range(1,4).Sum());\nif(threaded!=tasked) throw new Exception("results");Console.WriteLine(tasked);',
"هر دو نتیجه 10 باشند؛ هیچ thread یا task بی‌مالک باقی نماند. از این مثال تضمین سرعت بیشتر یا thread تازه برای هر Task استنتاج نشود.")

unit(87,
"race condition وقتی است که نتیجه به درهم‌تنیدگی نامطمئن عملیات مشترک وابسته شود. critical section باید تمام عملیات مرکب مرتبط را پوشش دهد،نه فقط یک خواندن یا نوشتن. lock/Monitor مالکیت متقابل می‌دهند؛ System.Threading.Lock از C#13 نوع اختصاصی قفل درون‌فرایندی است. Mutex می‌تواند سناریوی بین‌فرایندی،Semaphore سقف ورود و ReaderWriterLockSlim تفکیک خواندن/نوشتن را حل کند. await داخل lock مجاز نیست؛ برای gate async از SemaphoreSlim با WaitAsync و Release در finally استفاده کن. ترتیب ثابت گرفتن چند قفل خطر deadlock را کم می‌کند. لغو پیش از گرفتن gate نباید Release اضافه ایجاد کند.",
'int count=0;var gate=new System.Threading.Lock();\nParallel.For(0,1000,_=>{lock(gate) count++;});\nConsole.WriteLine(count);', '1000',
("Release در SemaphoreSlim کجا قرار می‌گیرد؟", "در finally فقط پس از WaitAsync موفق", "حتی اگر WaitAsync پیش از گرفتن لغو شده باشد", "فقط در مسیر موفق و بدون finally", "هر گرفتن موفق یک آزادسازی می‌خواهد؛ لغو قبل از گرفتن مالکیت ایجاد نمی‌کند."),
repair("مالکیت gate", "WaitAsync پیش از ورود try انجام شده و ممکن است لغو شود. جای Release را برای کار بعد از گرفتن انتخاب کن.", ["فقط پس از کار موفق", "finally پس از WaitAsync موفق", "قبل از WaitAsync"], [0], ["موفقیت آزاد می‌کند", "exception آزاد می‌کند", "لغو پیش از گرفتن Release اضافه ندارد"], [([0],[True,False,True]),([1],[True,True,True]),([2],[False,False,False])]),
"شمارندهٔ مشترک را با lock و 1000 افزایش تست کن. سپس gate async تک‌ورودی با token و finally بساز؛ لغو پیش از گرفتن و خطای داخل بخش را بررسی کن.",
'using var gate=new SemaphoreSlim(1,1);int count=0;\nasync Task Add(CancellationToken token) {await gate.WaitAsync(token);try {count++;} finally {gate.Release();}}\nawait Task.WhenAll(Enumerable.Range(0,100).Select(_=>Add(CancellationToken.None)));\nConsole.WriteLine(count);Console.WriteLine(gate.CurrentCount);',
"100 و 1 چاپ شود؛ شمارندهٔ نهایی دقیق و gate پس از خطا قابل استفاده بماند. هیچ await داخل lock یا Release بدون مالکیت وجود نداشته باشد.")

unit(88,
"atomicity یعنی عملیات تقسیم‌ناپذیر مشاهده شود؛ visibility و ordering دربارهٔ دیده‌شدن و ترتیب انتشار داده‌اند. volatile یا Volatile.Read/Write جای عملیات مرکب اتمیک مثل ++ را نمی‌گیرند. Interlocked برای increment،exchange و compare-exchange قرارداد اتمیک می‌دهد. compare-exchange فقط در صورت برابر بودن مقدار قبلی جایگزین می‌کند و مقدار قبلی را برمی‌گرداند. memory barrier و cache جزئیات مهم مدل حافظه‌اند،اما نباید با حدس از ترتیب CPU کد همزمان نوشت. الگوریتم lock-free اثبات دشوار و خطرهایی مثل ABA دارد؛ برای invariant چندمتغیره اغلب lock ساده‌تر و درست‌تر است.",
'int count=0;Parallel.For(0,1000,_=>Interlocked.Increment(ref count));\nConsole.WriteLine(count);', '1000',
("volatile int count; سپس count++ چه تضمینی ندارد؟", "اتمیک بودن کل خواندن،جمع و نوشتن", "قواعد visibility مربوط به volatile", "وجود نوع int", "++ عملیات مرکب است؛ برای شمارندهٔ مستقل Interlocked.Increment قرارداد اتمیک مناسب می‌دهد."),
simulation("گم‌شدن یک افزایش", "دو worker ابتدا count=0 را خوانده‌اند. با commit هر دو نشان بده نتیجهٔ ++ غیراتمیک ممکن است 1 شود.", ["A مقدار خوانده‌شده+1 را می‌نویسد", "B مقدار خوانده‌شده+1 را می‌نویسد"], ["A=0,B=0,count=0","A نوشته:count=1","B نوشته:count=1","هر دو نوشته‌اند:count=1"], [[1,2],[-1,3],[3,-1],[-1,-1]], [3], limit=2),
"Interlocked.CompareExchange را برای تغییر 0 به 1 تست کن؛ بار دوم با انتظار 0 نباید مقدار 2 را ثبت کند. شمارندهٔ اتمیک را هم با چند worker بسنج.",
'int state=0;Console.WriteLine(Interlocked.CompareExchange(ref state,1,0));\nConsole.WriteLine(Interlocked.CompareExchange(ref state,2,0));Console.WriteLine(state);\nint count=0;Parallel.For(0,1000,_=>Interlocked.Increment(ref count));if(count!=1000) throw new Exception("atomic");',
"0،1،1 چاپ شود و شمارنده 1000 باشد. volatile به‌جای اتمیک‌کردن عملیات مرکب پیشنهاد نشود؛ invariant چندعضوی جدا تحلیل شود.")

unit(89,
"ConcurrentDictionary،Queue،Stack و Bag عملیات همزمانِ مشخص را پشتیبانی می‌کنند؛ ترکیب چند فراخوانی الزاماً اتمیک نیست. BlockingCollection صف blocking با ظرفیت و completion می‌دهد و با Channel async هدف یکسان اجرایی ندارد. factory در GetOrAdd یا AddOrUpdate ممکن است چندبار اجرا شود،حتی اگر تنها یک مقدار ذخیره شود؛ side effect غیرidempotent نباید با فرض یک‌بار بودن در آن قرار گیرد. thread safety خود ظرف به ایمنی objectهای mutable داخلش سرایت نمی‌کند. برای تضمین ساخت یک‌بار می‌توان قرارداد مناسب Lazy یا مالکیت جدا سنجید،با رسیدگی به خطا و lifetime. enumeration و snapshot هر نوع را از مستندات خودش بخوان.",
'using System.Collections.Concurrent;\nvar counts=new ConcurrentDictionary<string,int>();\nParallel.For(0,100,_=>counts.AddOrUpdate("a",1,(_,n)=>n+1));\nConsole.WriteLine(counts["a"]);', '100',
("GetOrAdd در رقابت چند thread چه تضمینی دربارهٔ factory ندارد؟", "اجرای دقیقاً یک‌بارهٔ factory", "نگهداری یک مقدار برای همان کلید طبق قرارداد", "برگرداندن مقدار مربوط به کلید", "factory ممکن است بیرون قفل داخلی چندبار اجرا شود؛ اثر جانبی باید قرارداد تکرار داشته باشد."),
experiment("کارخانهٔ چندبارخوانده", "نتیجه‌های یک اجرای هماهنگ‌شده را ببین.", ["A و B هر دو کلید را غایب دیدند", "هر دو factory اجرا شد؛ یکی از مقدارها درج شد", "هر دو فراخوانی مقدار ذخیره‌شدهٔ همان کلید را گرفتند"], ["thread safety ظرف به معنی اجرای یک‌بارهٔ factory نیست.", "factory همیشه دقیقاً یک بار اجرا می‌شود.", "ConcurrentDictionary هیچ عملیات thread-safe ندارد."], 0),
"شمارش همزمان با AddOrUpdate بساز. تستی با هماهنگی کنترل‌شده نشان دهد factory GetOrAdd می‌تواند دوبار وارد شود؛ assertion را به sleep وابسته نکن.",
'using System.Collections.Concurrent;\nvar values=new ConcurrentDictionary<string,int>();using var barrier=new Barrier(2);int calls=0;\nint Factory(string key) {Interlocked.Increment(ref calls);barrier.SignalAndWait();return 7;}\nvar a=new Thread(()=>values.GetOrAdd("a",Factory));var b=new Thread(()=>values.GetOrAdd("a",Factory));\na.Start();b.Start();a.Join();b.Join();Console.WriteLine($"{calls},{values.Count},{values["a"]}");',
"2,1,7 چاپ شود؛ دو thread با Barrier به factory رسیده باشند. تست timeout حفاظتی داشته باشد تا شکست به hang تبدیل نشود؛ هیچ side effect واقعی انجام نشود.")

unit(90,
"Channel صف producer/consumer با API async و پایان مشخص است. bounded ظرفیت محدود دارد و در FullMode.Wait کندی مصرف‌کننده به producer فشار برمی‌گرداند؛ unbounded می‌تواند حافظه را با رشد صف مصرف کند. حالت‌های Drop قرارداد از دست‌رفتن داده دارند و باید عمدی انتخاب شوند. Writer completion و خطا را اعلام و Reader پایان را مشاهده می‌کند. cancellation انتظار را متوقف می‌کند و مالک producer/worker باید تمام taskها را در shutdown تعیین تکلیف کند. thread safety و پیاده‌سازی داخلی را نباید با ادعای عمومی lock-free بودن همهٔ Channelها خلاصه کرد. ظرفیت محدود به‌تنهایی اندازهٔ تک‌پیام یا منابع هر کار را محدود نمی‌کند.",
'using System.Threading.Channels;\nvar channel=Channel.CreateBounded<int>(1);await channel.Writer.WriteAsync(1);\nConsole.WriteLine(channel.Writer.TryWrite(2));Console.WriteLine(await channel.Reader.ReadAsync());channel.Writer.Complete();', 'False\n1',
("در bounded Channel با FullMode.Wait وقتی صف پر است چه انتظار داری؟", "WriteAsync تا ظرفیت یا لغو منتظر بماند.", "همیشه پیام بی‌خبر حذف شود.", "ظرفیت خودکار بی‌نهایت شود.", "backpressure در حالت Wait تولید را با مصرف هماهنگ می‌کند؛ سیاست Drop رفتار دیگری دارد."),
simulation("فشار برگشتی صف", "ظرفیت 1 است؛ ابتدا پیام A پر شده. هدف تحویل A و سپس ثبت B بدون حذف داده است.", ["Read A", "Write B", "Write B در صف پر"], ["صف=[A]","صف=[]،A تحویل شد","صف=[B]،A تحویل شد"], [[1,-1,-1],[-1,2,-1],[-1,-1,-1]], [2], limit=3),
"pipeline bounded با producer و consumer بساز. پس از تولید 1،2،3 writer کامل شود و consumer تمام داده را بگیرد. خطای producer و لغو را با مشاهدهٔ پایان همهٔ taskها تست کن.",
'using System.Threading.Channels;\nvar channel=Channel.CreateBounded<int>(1);\nasync Task Produce() {try {for(int i=1;i<=3;i++) await channel.Writer.WriteAsync(i);channel.Writer.TryComplete();} catch(Exception e) {channel.Writer.TryComplete(e);throw;}}\nasync Task<int> Consume() {int sum=0;await foreach(int n in channel.Reader.ReadAllAsync()) sum+=n;return sum;}\nTask producer=Produce();Task<int> consumer=Consume();await Task.WhenAll(producer,consumer);Console.WriteLine(await consumer);',
"6 چاپ شود؛ completion و خطا مشاهده شوند. در شکست یا لغو consumer،producer هم لغو و awaited شود تا در صف پر رها نماند.")

unit(91,
"Parallel.For/ForEach برای کارهای مستقل CPU و ForEachAsync برای بدنهٔ async با سقف همزمانی مناسب‌اند. MaxDegreeOfParallelism فشار روی منبع را محدود می‌کند ولی همهٔ زمان‌بندی‌ها را ثابت نمی‌کند. PLINQ با AsParallel query را parallel می‌کند؛ حفظ ترتیب با AsOrdered هزینه دارد و همیشه لازم نیست. partitioning تقسیم داده و overhead هماهنگی می‌سازد؛ برای ورودی کوچک نسخهٔ ترتیبی ممکن است بهتر باشد. نوشتن در دادهٔ مشترک باید حذف یا synchronize شود. نتیجه باید با نسخهٔ ترتیبی هم‌رفتار باشد. تعداد taskها را با تعداد core یا سقف اتصال بدون سنجش یکی فرض نکن.",
'int[] values={1,2,3};int[] result=new int[3];\nParallel.For(0,values.Length,i=>result[i]=values[i]*2);\nConsole.WriteLine(string.Join(",",result));', '2,4,6',
("برای بدنهٔ async با حداکثر 4 کار همزمان کدام قرارداد روشن‌تر است؟", "Parallel.ForEachAsync با MaxDegreeOfParallelism=4", "ساخت نامحدود task و امید به pool", "نوشتن در List مشترک بدون قفل", "سقف صریح از فشار نامحدود جلوگیری می‌کند؛ نتیجه و لغو همچنان باید مدیریت شوند."),
budget("همزمانی محدود", "طرح باید سقف 4،خروجی مستقل و لغو داشته باشد؛ هزینه‌ها فرضی‌اند.", ["ForEachAsync با سقف 4", "جایگاه خروجی مستقل", "انتقال token", "List مشترک بی‌قفل"], [1,1,1,2], [["سقف"],["داده"],["لغو"],[]], ["سقف","داده","لغو"], 3, [0,1,2]),
"پردازش [1,2,3,4] را با ForEachAsync و سقف 2 انجام بده. خروجی با نسخهٔ ترتیبی برابر باشد؛ آزمون سقف با gate کنترل‌شده باشد،نه sleep.",
'int[] input={1,2,3,4};int[] output=new int[input.Length];\nawait Parallel.ForEachAsync(Enumerable.Range(0,input.Length),new ParallelOptions {MaxDegreeOfParallelism=2},async (i,token)=>{token.ThrowIfCancellationRequested();await Task.CompletedTask;output[i]=input[i]*2;});\nif(!output.SequenceEqual(input.Select(n=>n*2))) throw new Exception("parallel");Console.WriteLine(string.Join(",",output));',
"2,4,6,8 چاپ شود. دادهٔ مشترک نامطمئن وجود نداشته باشد؛ تست جدا تعداد کارهای فعال و لغو را بسنجد.")

unit(92,
"SynchronizationContext مسیر ادامهٔ async را در محیط‌هایی مانند UI کنترل می‌کند؛ ExecutionContext دادهٔ جریان منطقی از جمله AsyncLocal را منتقل می‌کند. TaskScheduler انتخاب اجرای task را بیان می‌کند و با دو context یکی نیست. ConfigureAwait(false) عمدتاً capture مربوط به context انتظار را تغییر می‌دهد و همهٔ ExecutionContext را خاموش نمی‌کند. کد کتابخانه و برنامه نیازهای متفاوت دارند؛ توصیهٔ همگانی بدون context درست نیست. sync-over-async روی context تک‌thread می‌تواند deadlock و روی pool فشار و starvation بسازد. رفع ریشه معمولاً async در تمام زنجیره و مالکیت کار است،نه افزودن کور Task.Run. جریان context و اشتراک وضعیت را با تست کوچک مشاهده کن.",
'var local=new AsyncLocal<string?>();local.Value="parent";\nawait Task.Run(()=>{Console.WriteLine(local.Value);local.Value="child";});\nConsole.WriteLine(local.Value);', 'parent\nparent',
("ConfigureAwait(false) آیا تمام AsyncLocalها را خودکار پاک می‌کند؟", "خیر؛ ExecutionContext با SynchronizationContext متفاوت است.", "بله؛ همهٔ contextها همیشه حذف می‌شوند.", "بله؛ task دیگر خطا نمی‌دهد.", "سیاست ادامهٔ await با انتقال دادهٔ جریان منطقی دو سازوکار جداست."),
conflict("ادعای context", "این ادعاها دربارهٔ همان اجرای ConfigureAwait(false) هستند؛ تناقض حداقلی را پیدا کن.", ["AsyncLocal از ExecutionContext جریان می‌یابد", "ConfigureAwait(false) الزاماً همهٔ ExecutionContext را حذف می‌کند", "در این اجرا AsyncLocal پس از await مقدار جریان‌یافته دارد"], [([1,2],[1,2],"مشاهدهٔ جریان AsyncLocal با ادعای حذف همیشگی آن ناسازگار است.")]),
"زنجیرهٔ async بدون Result/Wait بساز و AsyncLocal را در Task.Run مشاهده کن. سناریوی deadlock UI را با نمودار انتظار توضیح بده؛ کد hangشونده را در فرایند اصلی تست اجرا نکن.",
'var context=new AsyncLocal<string?> {Value="request"};\nawait ObserveAsync();Console.WriteLine(context.Value);\nasync Task ObserveAsync(){await Task.CompletedTask.ConfigureAwait(false);Console.WriteLine(context.Value);}',
"request دو بار چاپ شود. علت deadlock از چرخهٔ انتظار UI و ادامه توضیح داده شود؛ ConfigureAwait به‌عنوان درمان عمومی تمام مسائل توصیه نشود.")

unit(93,
"تست همزمانی باید رسیدن workerها به نقطهٔ مشخص را با TCS،Barrier یا gate کنترل کند،نه با خواب تصادفی. زمان timeout را با TimeProvider قابل کنترل از زمان اجرای تست جدا کن. race باید با ترتیب بازتولیدپذیر و assertion روی invariant بررسی شود. Activity/ActivitySource spanهای یک عملیات و رابطهٔ والد/فرزند را بیان می‌کنند؛ listener یا اتصال OpenTelemetry داده را جمع می‌کند. EventSource و counters نمای رویداد و اندازه‌گیری می‌دهند و جای log متنی ساده نیستند. trace باید هویت عملیات را بدون secret منتقل کند. فعال‌بودن sampling و listener بر وجود span اثر دارد؛ نبود span همیشه به معنای نبود اجرا نیست.",
'var gate=new TaskCompletionSource<int>(TaskCreationOptions.RunContinuationsAsynchronously);\nasync Task<int> Worker()=>await gate.Task;\nTask<int> work=Worker();Console.WriteLine(work.IsCompleted);gate.SetResult(3);Console.WriteLine(await work);', 'False\n3',
("برای اثبات رسیدن worker به critical point کدام بهتر است؟", "signal و gate صریح با timeout حفاظتی", "sleep طولانی و امید به زمان‌بندی", "حذف assertion همزمانی", "هماهنگی صریح ترتیب تست را مشخص می‌کند؛ timeout فقط محافظ hang است،نه ابزار اثبات رسیدن."),
constraints("تست بدون sleep", "تست باید ابتدا شروع worker را ببیند،سپس اجازهٔ ادامه بدهد و پایان را مشاهده کند.", ["شروع worker", "worker نقطهٔ ورود را signal می‌کند", "تست signal را await می‌کند", "تست gate ادامه را باز می‌کند", "await پایان و assert"], [[0,1],[1,2],[2,3],[3,4]]),
"تست لغو worker را با دو TCS برای ورود و ادامه بساز. ActivitySource برای یک عملیات و child داشته باش؛ listener تست تعداد و رابطهٔ spanها را ثبت کند.",
'using System.Diagnostics;\nvar names=new List<string>();using var listener=new ActivityListener {ShouldListenTo=s=>s.Name=="ILearn.Sample",Sample=(ref ActivityCreationOptions<ActivityContext> options)=>ActivitySamplingResult.AllData,ActivityStopped=a=>names.Add(a.OperationName)};\nActivitySource.AddActivityListener(listener);using var source=new ActivitySource("ILearn.Sample");\nusing(var parent=source.StartActivity("parent")) {using var child=source.StartActivity("child");}\nConsole.WriteLine(string.Join(",",names));',
"child,parent چاپ شود. listener قبل از شروع span ثبت و disposed شود؛ هماهنگی worker و لغو بدون sleep در تست جدا اثبات شوند.")

unit(94,
"پروژهٔ async باید تولید،مصرف و shutdown را یک قرارداد واحد ببیند. صف bounded فشار برگشتی را مشخص می‌کند؛ token مشترک یا linked cancellation باید شکست یک سمت را به سمت منتظر منتقل کند. writer پایان یا خطا را اعلام می‌کند و همهٔ workerها awaited می‌شوند. مصرف تدریجی از انباشتن نامحدود داده جلوگیری می‌کند،اما اندازهٔ پیام و سقف کار هم باید محدود باشند. retry فقط در مرز idempotent مجاز است. تست باید موفقیت،خطای یک کار،لغو و کندی مقصد را با gateهای کنترل‌شده بررسی کند. رها نکردن task و منبع معیار پایان است؛ چاپ چند نتیجه به‌تنهایی تحویل pipeline نیست.",
'using System.Threading.Channels;\nvar queue=Channel.CreateBounded<int>(1);\nawait queue.Writer.WriteAsync(4);queue.Writer.Complete();\nawait foreach(int n in queue.Reader.ReadAllAsync()) Console.WriteLine(n*2);', '8',
("اگر consumer شکست بخورد و producer روی صف پر منتظر بماند،چه لازم است؟", "لغو producer،تکمیل مناسب صف و await همهٔ کارها", "رهاکردن producer در پس‌زمینه", "فقط چاپ پیام موفقیت", "شکست باید انتظار سمت دیگر را باز کند؛ مالک pipeline مسئول تعیین تکلیف تمام taskهاست."),
mission("خاموشی پردازشگر", "در هر وضعیت مالکیت task و پایان صف را نگه دار.", [("consumer خطا داده و producer روی WriteAsync منتظر است.","لغو token مشترک","رهاکردن producer"),("درخواست لغو به writer رسیده است.","اعلام completion و مشاهدهٔ خطا","بلعیدن خطا و ادامهٔ نامحدود"),("همهٔ taskها تعیین تکلیف شده‌اند.","آزادسازی منابع و گزارش نتیجهٔ واقعی","گزارش موفقیت قبل از پایان cleanup")]),
"پردازشگر bounded با دو consumer بساز. لغو و خطای هر سمت باید طرف دیگر را متوقف کند؛ تمام taskها مشاهده شوند. نمونهٔ مرجع مالکیت پایان و لغو مشترک را نشان می‌دهد.",
'using System.Threading.Channels;\nusing var stop=new CancellationTokenSource();var queue=Channel.CreateBounded<int>(2);int total=0;\nasync Task Produce() {try {for(int i=1;i<=4;i++) await queue.Writer.WriteAsync(i,stop.Token);queue.Writer.TryComplete();} catch(Exception e) {queue.Writer.TryComplete(e);stop.Cancel();throw;}}\nasync Task Consume() {try {await foreach(int n in queue.Reader.ReadAllAsync(stop.Token)) Interlocked.Add(ref total,n);} catch {stop.Cancel();throw;}}\nTask producer=Produce();Task a=Consume(),b=Consume();\ntry {await Task.WhenAll(producer,a,b);} finally {stop.Cancel();}\nConsole.WriteLine(total);',
"جمع 10 باشد و همهٔ taskها پایان یابند. fault و لغو با timeout حفاظتی و gate تست شوند؛ در شکست مصرف‌کننده producer روی صف پر نماند.")
